"""Project creation, persistence, profiles, and validation for CapCut CLI."""

from copy import deepcopy
from datetime import datetime, timezone
import json
import os
from typing import Any, Dict, List, Optional

from cli_anything.capcut.core.session import _locked_save_json
from cli_anything.capcut.utils.capcut_backend import ensure_pycapcut

PROFILES: Dict[str, Dict[str, int]] = {
    "hd1080p": {"width": 1920, "height": 1080, "fps": 30},
    "hd1080p60": {"width": 1920, "height": 1080, "fps": 60},
    "vertical_1080p": {"width": 1080, "height": 1920, "fps": 30},
    "vertical_1080p60": {"width": 1080, "height": 1920, "fps": 60},
    "uhd4k": {"width": 3840, "height": 2160, "fps": 30},
    "uhd4k60": {"width": 3840, "height": 2160, "fps": 60},
    "square_1080": {"width": 1080, "height": 1080, "fps": 30},
    "hd720p": {"width": 1280, "height": 720, "fps": 30},
}


def list_profiles() -> List[Dict[str, Any]]:
    """Return available canvas resolution and frame-rate profiles."""
    return [
        {
            "name": name,
            "width": cfg["width"],
            "height": cfg["height"],
            "fps": cfg["fps"],
        }
        for name, cfg in PROFILES.items()
    ]


def create(
    name: str = "Untitled CapCut Draft",
    width: int = 1920,
    height: int = 1080,
    fps: int = 30,
    profile: Optional[str] = None,
    maintrack_adsorb: bool = True,
    output_path: Optional[str] = None,
) -> Dict[str, Any]:
    """Create a new CapCut CLI project dictionary and optionally save it to disk."""
    if profile:
        if profile not in PROFILES:
            raise ValueError(
                f"Unknown profile '{profile}'. Valid profiles: {', '.join(PROFILES)}"
            )
        p = PROFILES[profile]
        width, height, fps = p["width"], p["height"], p["fps"]

    if width <= 0 or height <= 0:
        raise ValueError(f"Canvas dimensions must be positive (got {width}x{height}).")
    if fps <= 0 or fps > 240:
        raise ValueError(f"FPS must be between 1 and 240 (got {fps}).")

    project: Dict[str, Any] = {
        "schema": "cli-anything-capcut/v1",
        "name": name,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "canvas": {
            "width": int(width),
            "height": int(height),
            "fps": int(fps),
            "maintrack_adsorb": bool(maintrack_adsorb),
        },
        "tracks": [],
        "segments": [],
        "srt_imports": [],
        "duration_us": 0,
    }

    if output_path:
        save(project, output_path)
    return project


create_project = create


def open(path: str) -> Dict[str, Any]:
    """Open a CLI-Anything CapCut project file or native `draft_content.json`."""
    abs_path = os.path.abspath(path)
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Project file not found: {abs_path}")

    with builtins_open(abs_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Support opening either our project schema or a raw CapCut draft_content.json
    if data.get("schema") == "cli-anything-capcut/v1":
        return data

    if "canvas_config" in data and "tracks" in data and "materials" in data:
        cc_canvas = data.get("canvas_config", {})
        return {
            "schema": "cli-anything-capcut/v1",
            "name": os.path.basename(os.path.dirname(abs_path)) or "Imported Draft",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "canvas": {
                "width": int(cc_canvas.get("width", 1920)),
                "height": int(cc_canvas.get("height", 1080)),
                "fps": int(data.get("fps", 30)),
                "maintrack_adsorb": bool(
                    data.get("config", {}).get("maintrack_adsorb", True)
                ),
            },
            "tracks": [
                {
                    "name": t.get("name") or t.get("type", "video"),
                    "type": t.get("type", "video"),
                    "mute": bool(t.get("attribute", 0)),
                    "relative_index": 0,
                }
                for t in data.get("tracks", [])
            ],
            "segments": [],
            "srt_imports": [],
            "duration_us": int(data.get("duration", 0)),
            "native_draft_path": abs_path,
        }

    raise ValueError(f"Unrecognized CapCut project format in {abs_path}")


def builtins_open(*args: Any, **kwargs: Any) -> Any:
    """Wrapper around built-in open since module defines `open`."""
    import builtins

    return builtins.open(*args, **kwargs)


open_project = open


def save(project: Dict[str, Any], path: str) -> str:
    """Save a CapCut project dictionary to `path` using locked JSON write."""
    abs_path = os.path.abspath(path)
    recompute_duration(project)
    _locked_save_json(abs_path, project, indent=2, ensure_ascii=False)
    return abs_path


save_project = save


def recompute_duration(project: Dict[str, Any]) -> int:
    """Recompute and update `project['duration_us']` from all segments."""
    max_end = 0
    for seg in project.get("segments", []):
        end_us = int(seg.get("target_start_us", 0)) + int(
            seg.get("target_duration_us", 0)
        )
        if end_us > max_end:
            max_end = end_us
    project["duration_us"] = max_end
    return max_end


def info(project: Dict[str, Any]) -> Dict[str, Any]:
    """Return structured summary of the CapCut project."""
    recompute_duration(project)
    canvas = project.get("tracks", [])
    segs = project.get("segments", [])
    dur_us = int(project.get("duration_us", 0))

    seg_counts: Dict[str, int] = {}
    for s in segs:
        k = s.get("kind", "unknown")
        seg_counts[k] = seg_counts.get(k, 0) + 1

    return {
        "name": project.get("name", "Untitled"),
        "schema": project.get("schema", "cli-anything-capcut/v1"),
        "canvas": deepcopy(project.get("canvas", {})),
        "duration_us": dur_us,
        "duration_seconds": round(dur_us / 1_000_000, 3),
        "track_count": len(canvas),
        "tracks": deepcopy(canvas),
        "segment_count": len(segs),
        "segments_by_kind": seg_counts,
        "srt_import_count": len(project.get("srt_imports", [])),
    }


project_info = info


def validate_project(project: Dict[str, Any]) -> Dict[str, Any]:
    """Validate project schema, track references, and segment overlaps."""
    ensure_pycapcut()
    errors: List[str] = []
    warnings: List[str] = []

    if project.get("schema") != "cli-anything-capcut/v1":
        errors.append("Missing or invalid schema field.")

    canvas = project.get("canvas", {})
    if int(canvas.get("width", 0)) <= 0 or int(canvas.get("height", 0)) <= 0:
        errors.append("Canvas width and height must be positive integers.")

    track_map = {t["name"]: t for t in project.get("tracks", []) if "name" in t}
    by_track: Dict[str, List[Dict[str, Any]]] = {name: [] for name in track_map}

    for idx, seg in enumerate(project.get("segments", [])):
        t_name = seg.get("track")
        if t_name not in track_map:
            errors.append(f"Segment #{idx} references unknown track '{t_name}'.")
            continue
        by_track[t_name].append(seg)
        if seg.get("kind") in ("video", "audio") and seg.get("path"):
            if not os.path.exists(seg["path"]):
                warnings.append(f"Media file does not exist on disk: {seg['path']}")

    for t_name, t_segs in by_track.items():
        sorted_segs = sorted(t_segs, key=lambda s: int(s.get("target_start_us", 0)))
        for i in range(len(sorted_segs) - 1):
            curr_end = int(sorted_segs[i].get("target_start_us", 0)) + int(
                sorted_segs[i].get("target_duration_us", 0)
            )
            next_start = int(sorted_segs[i + 1].get("target_start_us", 0))
            if curr_end > next_start:
                errors.append(
                    f"Overlapping segments on track '{t_name}' at {next_start}us."
                )

    return {
        "valid": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
        "track_count": len(track_map),
        "segment_count": len(project.get("segments", [])),
    }

"""Track management operations for CapCut CLI projects."""

from copy import deepcopy
from typing import Any, Dict, List, Optional

VALID_TRACK_TYPES = ("video", "audio", "text", "effect", "filter", "sticker")


def add_track(
    project: Dict[str, Any],
    track_type: str,
    name: Optional[str] = None,
    mute: bool = False,
    relative_index: int = 0,
) -> Dict[str, Any]:
    """Add a new track of `track_type` to the project."""
    t_type = track_type.lower().strip()
    if t_type not in VALID_TRACK_TYPES:
        raise ValueError(
            f"Invalid track type '{track_type}'. Must be one of: {', '.join(VALID_TRACK_TYPES)}"
        )

    tracks: List[Dict[str, Any]] = project.setdefault("tracks", [])
    existing_names = {t["name"] for t in tracks}
    same_type_tracks = [t for t in tracks if t["type"] == t_type]

    if name is None:
        if same_type_tracks:
            raise NameError(
                f"A '{t_type}' track already exists; please specify a unique `--name`."
            )
        name = t_type

    if name in existing_names:
        raise NameError(f"Track named '{name}' already exists.")

    track_entry = {
        "name": name,
        "type": t_type,
        "mute": bool(mute),
        "relative_index": int(relative_index),
    }
    tracks.append(track_entry)
    return deepcopy(track_entry)


def list_tracks(project: Dict[str, Any]) -> List[Dict[str, Any]]:
    """List all tracks in the project with segment counts."""
    tracks = project.get("tracks", [])
    segments = project.get("segments", [])
    result: List[Dict[str, Any]] = []
    for trk in tracks:
        t_segs = [s for s in segments if s.get("track") == trk["name"]]
        dur_us = 0
        for s in t_segs:
            end_us = int(s.get("target_start_us", 0)) + int(
                s.get("target_duration_us", 0)
            )
            if end_us > dur_us:
                dur_us = end_us
        item = deepcopy(trk)
        item["segment_count"] = len(t_segs)
        item["duration_us"] = dur_us
        item["duration_seconds"] = round(dur_us / 1_000_000, 3)
        result.append(item)
    return result


def remove_track(project: Dict[str, Any], name: str) -> Dict[str, Any]:
    """Remove a track and all segments assigned to it."""
    tracks = project.get("tracks", [])
    target = next((t for t in tracks if t["name"] == name), None)
    if target is None:
        raise NameError(f"Track '{name}' not found.")

    project["tracks"] = [t for t in tracks if t["name"] != name]
    before_segs = len(project.get("segments", []))
    project["segments"] = [
        s for s in project.get("segments", []) if s.get("track") != name
    ]
    removed_segs = before_segs - len(project["segments"])

    from cli_anything.capcut.core.project import recompute_duration

    recompute_duration(project)
    return {
        "removed_track": name,
        "removed_segments": removed_segs,
    }


def set_track_mute(
    project: Dict[str, Any], name: str, mute: bool = True
) -> Dict[str, Any]:
    """Set the mute state of a track."""
    tracks = project.get("tracks", [])
    target = next((t for t in tracks if t["name"] == name), None)
    if target is None:
        raise NameError(f"Track '{name}' not found.")
    target["mute"] = bool(mute)
    return deepcopy(target)

"""Template mode and CapCut DraftFolder management operations."""

import json
import os
from typing import Any, Dict, List, Optional

from cli_anything.capcut.utils.capcut_backend import ensure_pycapcut, find_capcut_app


def resolve_drafts_folder(folder_path: Optional[str] = None) -> str:
    """Resolve the CapCut Drafts folder path or raise FileNotFoundError."""
    if folder_path:
        abs_folder = os.path.abspath(folder_path)
        if not os.path.isdir(abs_folder):
            raise FileNotFoundError(f"Drafts folder not found: {abs_folder}")
        return abs_folder

    app_info = find_capcut_app()
    if app_info.get("drafts_dir"):
        return str(app_info["drafts_dir"])
    raise FileNotFoundError(
        "No CapCut Drafts folder specified and default CapCut Drafts directory was not found."
    )


def list_drafts_in_folder(folder_path: Optional[str] = None) -> Dict[str, Any]:
    """List all CapCut drafts in a DraftFolder."""
    cc = ensure_pycapcut()
    resolved = resolve_drafts_folder(folder_path)
    df = cc.DraftFolder(resolved)
    names = df.list_drafts()
    drafts: List[Dict[str, Any]] = []
    for name in sorted(names):
        dpath = os.path.join(resolved, name)
        content_json = os.path.join(dpath, "draft_content.json")
        has_content = os.path.exists(content_json)
        drafts.append(
            {
                "name": name,
                "path": dpath,
                "has_draft_content": has_content,
            }
        )
    return {
        "folder_path": resolved,
        "count": len(drafts),
        "drafts": drafts,
    }


def inspect_draft_materials(
    draft_content_or_dir: str,
) -> Dict[str, Any]:
    """Inspect tracks and materials of an existing CapCut draft (`draft_content.json` or draft dir)."""
    cc = ensure_pycapcut()
    abs_target = os.path.abspath(draft_content_or_dir)
    if os.path.isdir(abs_target):
        json_path = os.path.join(abs_target, "draft_content.json")
    else:
        json_path = abs_target

    if not os.path.exists(json_path):
        raise FileNotFoundError(f"draft_content.json not found at: {json_path}")

    script = cc.ScriptFile.load_template(json_path)
    mats = script.imported_materials

    stickers = [
        {"resource_id": s.get("resource_id"), "name": s.get("name", "")}
        for s in mats.get("stickers", [])
    ]
    bubbles = [
        {
            "effect_id": e.get("effect_id"),
            "resource_id": e.get("resource_id"),
            "name": e.get("name", ""),
        }
        for e in mats.get("effects", [])
        if e.get("type") == "text_shape"
    ]
    text_effects = [
        {"resource_id": e.get("resource_id"), "name": e.get("name", "")}
        for e in mats.get("effects", [])
        if e.get("type") == "text_effect"
    ]
    videos = [
        {
            "id": v.get("id"),
            "material_name": v.get("material_name", ""),
            "path": v.get("path", ""),
            "duration_us": v.get("duration", 0),
        }
        for v in mats.get("videos", [])
    ]
    audios = [
        {
            "id": a.get("id"),
            "name": a.get("name", ""),
            "path": a.get("path", ""),
            "duration_us": a.get("duration", 0),
        }
        for a in mats.get("audios", [])
    ]
    texts: List[Dict[str, Any]] = []
    for t in mats.get("texts", []):
        raw_content = t.get("content", "")
        parsed_text = raw_content
        try:
            parsed_text = json.loads(raw_content).get("text", raw_content)
        except Exception:
            pass
        texts.append({"id": t.get("id"), "text": parsed_text})

    return {
        "draft_content_path": json_path,
        "width": script.width,
        "height": script.height,
        "fps": script.fps,
        "duration_us": script.duration,
        "imported_track_count": len(script.imported_tracks),
        "videos": videos,
        "audios": audios,
        "texts": texts,
        "stickers": stickers,
        "text_bubbles": bubbles,
        "text_effects": text_effects,
    }


def replace_template_text(
    draft_content_or_dir: str,
    track_index: int,
    segment_index: int,
    new_text: str,
    output_path: Optional[str] = None,
) -> Dict[str, Any]:
    """Replace text in a template draft's text track and save."""
    cc = ensure_pycapcut()
    abs_target = os.path.abspath(draft_content_or_dir)
    json_path = (
        os.path.join(abs_target, "draft_content.json")
        if os.path.isdir(abs_target)
        else abs_target
    )
    script = cc.ScriptFile.load_template(json_path)
    text_track = script.get_imported_track(cc.TrackType.text, index=int(track_index))
    script.replace_text(text_track, int(segment_index), new_text)

    save_to = os.path.abspath(output_path) if output_path else json_path
    script.dump(save_to)
    return {
        "draft_content_path": save_to,
        "track_index": track_index,
        "segment_index": segment_index,
        "new_text": new_text,
    }


def replace_template_media_by_name(
    draft_content_or_dir: str,
    material_name: str,
    new_media_path: str,
    is_video: bool = True,
    output_path: Optional[str] = None,
) -> Dict[str, Any]:
    """Replace a video or audio material by name in a template draft and save."""
    cc = ensure_pycapcut()
    abs_target = os.path.abspath(draft_content_or_dir)
    json_path = (
        os.path.join(abs_target, "draft_content.json")
        if os.path.isdir(abs_target)
        else abs_target
    )
    script = cc.ScriptFile.load_template(json_path)
    new_mat = (
        cc.VideoMaterial(new_media_path)
        if is_video
        else cc.AudioMaterial(new_media_path)
    )
    script.replace_material_by_name(material_name, new_mat)

    save_to = os.path.abspath(output_path) if output_path else json_path
    script.dump(save_to)
    return {
        "draft_content_path": save_to,
        "replaced_material_name": material_name,
        "new_media_path": os.path.abspath(new_media_path),
    }

"""Main Click CLI and stateful REPL entry point for cli-anything-capcut."""

import functools
import json
import shlex
import sys
from typing import Any, Callable, Dict, List, Optional

import click

from cli_anything.capcut import __version__
from cli_anything.capcut.core import (
    effects as effects_mod,
    export as export_mod,
    media as media_mod,
    project as proj_mod,
    session as sess_mod,
    template as tmpl_mod,
    text as text_mod,
    track as track_mod,
)
from cli_anything.capcut.core.session import get_session
from cli_anything.capcut.utils.capcut_backend import find_capcut_app, probe_media
from cli_anything.capcut.utils.repl_skin import ReplSkin

_repl_mode: bool = False
_json_mode: bool = False


def _emit(data: Any, human_lines: Optional[List[str]] = None) -> None:
    """Output structured JSON in `--json` mode or human-readable lines otherwise."""
    if _json_mode:
        click.echo(json.dumps(data, indent=2, ensure_ascii=False))
        return
    if human_lines is not None:
        for line in human_lines:
            click.echo(line)
    else:
        click.echo(json.dumps(data, indent=2, ensure_ascii=False))


def handle_error(func: Callable[..., Any]) -> Callable[..., Any]:
    """Decorator providing consistent human/JSON error reporting across commands."""

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        try:
            return func(*args, **kwargs)
        except Exception as exc:
            if _json_mode:
                click.echo(
                    json.dumps(
                        {
                            "status": "error",
                            "error": str(exc),
                            "type": type(exc).__name__,
                        },
                        ensure_ascii=False,
                    )
                )
            else:
                click.echo(f"Error: {exc}", err=True)
            if not _repl_mode:
                sys.exit(1)
            return None

    return wrapper


@click.group(invoke_without_command=True)
@click.version_option(__version__, prog_name="cli-anything-capcut")
@click.option("--json", "use_json", is_flag=True, default=False, help="Output as JSON")
@click.option(
    "--project",
    "project_path",
    type=str,
    default=None,
    help="Path to CapCut CLI project JSON file",
)
@click.option(
    "--dry-run",
    "dry_run",
    is_flag=True,
    default=False,
    help="Run command without saving changes to disk",
)
@click.pass_context
@handle_error
def cli(
    ctx: click.Context,
    use_json: bool,
    project_path: Optional[str],
    dry_run: bool,
) -> None:
    """CapCut CLI harness powered by pyCapCut and FFmpeg."""
    global _json_mode
    _json_mode = bool(use_json)
    ctx.ensure_object(dict)
    ctx.obj["json"] = _json_mode
    ctx.obj["dry_run"] = bool(dry_run)

    if project_path:
        sess = get_session()
        proj = proj_mod.open_project(project_path)
        sess.set_project(proj, project_path)

    if ctx.invoked_subcommand is None:
        ctx.invoke(repl, project_path=project_path)


@cli.result_callback()
def auto_save_on_exit(
    result: Any,
    use_json: bool,
    project_path: Optional[str],
    dry_run: bool,
    **kwargs: Any,
) -> None:
    """Auto-save project after one-shot commands if state was modified."""
    if _repl_mode or dry_run:
        return
    sess = get_session()
    if sess.has_project() and sess._modified and sess.project_path:
        try:
            sess.save_session()
        except Exception as exc:
            click.echo(f"Warning: Auto-save failed: {exc}", err=True)


# ---------------------------------------------------------------------------
# project group
# ---------------------------------------------------------------------------
@cli.group()
def project() -> None:
    """Create, open, save, inspect, and validate CapCut projects."""


@project.command("new")
@click.option("--name", "-n", default="Untitled CapCut Draft", help="Project name")
@click.option("--width", "-w", type=int, default=1920, help="Canvas width in pixels")
@click.option("--height", "-h", type=int, default=1080, help="Canvas height in pixels")
@click.option("--fps", "-r", type=int, default=30, help="Frames per second")
@click.option("--profile", "-p", type=str, default=None, help="Canvas profile name")
@click.option(
    "--adsorb/--no-adsorb",
    default=True,
    help="Enable or disable CapCut maintrack magnet",
)
@click.option("--output", "-o", type=str, default=None, help="Output project JSON path")
@handle_error
def project_new(
    name: str,
    width: int,
    height: int,
    fps: int,
    profile: Optional[str],
    adsorb: bool,
    output: Optional[str],
) -> None:
    """Create a new CapCut project."""
    proj = proj_mod.create_project(
        name=name,
        width=width,
        height=height,
        fps=fps,
        profile=profile,
        maintrack_adsorb=adsorb,
        output_path=output,
    )
    sess = get_session()
    sess.set_project(proj, output)
    res = proj_mod.project_info(proj)
    res["status"] = "created"
    res["output"] = sess.project_path
    c = res["canvas"]
    _emit(
        res,
        [
            f"Created CapCut project '{res['name']}' ({c['width']}x{c['height']} @ {c['fps']}fps)",
            *(
                [f"Saved to: {sess.project_path}"]
                if sess.project_path
                else []
            ),
        ],
    )


@project.command("open")
@click.argument("path")
@handle_error
def project_open(path: str) -> None:
    """Open an existing CapCut CLI project file or native draft_content.json."""
    proj = proj_mod.open_project(path)
    sess = get_session()
    sess.set_project(proj, path)
    info = proj_mod.project_info(proj)
    info["status"] = "opened"
    info["path"] = sess.project_path
    _emit(
        info,
        [
            f"Opened project '{info['name']}' from {sess.project_path}",
            f"Tracks: {info['track_count']}, Segments: {info['segment_count']}, Duration: {info['duration_seconds']}s",
        ],
    )


@project.command("save")
