@handle_error
def project_profiles() -> None:
    """List standard canvas resolution and FPS profiles."""
    profiles = proj_mod.list_profiles()
    lines = ["Available CapCut Canvas Profiles:"]
    for p in profiles:
        lines.append(f"  {p['name']:<18} {p['width']}x{p['height']} @ {p['fps']}fps")
    _emit({"profiles": profiles}, lines)


@project.command("validate")
@handle_error
def project_validate() -> None:
    """Validate project schema, tracks, and segment timeline consistency."""
    sess = get_session()
    proj = sess.require_project()
    report = proj_mod.validate_project(proj)
    status_str = "VALID" if report["valid"] else "INVALID"
    lines = [
        f"Validation: {status_str} (tracks={report['track_count']}, segments={report['segment_count']})"
    ]
    for err in report["errors"]:
        lines.append(f"  [ERROR] {err}")
    for warn in report["warnings"]:
        lines.append(f"  [WARN]  {warn}")
    _emit(report, lines)


