@cli.command("repl")
@click.option("--project", "project_path", type=str, default=None, help="Optional project file to load")
def repl(project_path: Optional[str] = None) -> None:
    """Start interactive CapCut CLI REPL session."""
    global _repl_mode
    _repl_mode = True
    sess = get_session()
    if project_path and not sess.has_project():
        proj = proj_mod.open_project(project_path)
        sess.set_project(proj, project_path)

    skin = ReplSkin("capcut", version=__version__)
    skin.print_banner()
    pt_session = skin.create_prompt_session()

    commands_help: Dict[str, str] = {
        "project new|open|save|info|profiles|validate": "Create, load, save, or validate CapCut project",
        "track add|list|remove|mute": "Manage timeline tracks (video, audio, text, effect, filter)",
        "media add-video|add-audio|list|remove|transform|fade|chroma|mask|blend|keyframe|probe": "Add and edit media clips",
        "text add|import-srt|list": "Add styled text or import SRT subtitles",
        "effect list-presets|add-filter|add-video-effect|add-audio-effect|add-transition|add-animation": "Apply CapCut effects & filters",
        "template list-drafts|inspect|replace-text|replace-media": "Template mode operations on CapCut drafts",
        "export presets|draft|render": "Export CapCut draft folder or render via FFmpeg",
        "session status|undo|redo|history|clear": "Session state and undo/redo",
        "help / quit / exit": "Show help or exit REPL",
    }

    while True:
        proj_name = sess.project.get("name", "untitled") if sess.has_project() else ""
        try:
            line = skin.get_input(
                pt_session, project_name=proj_name, modified=sess._modified
            )
        except (EOFError, KeyboardInterrupt):
            break

        raw = line.strip()
        if not raw:
            continue
        if raw in ("quit", "exit", "q"):
            break
        if raw in ("help", "?"):
            skin.help(commands_help)
            continue

        try:
            args = shlex.split(raw)
        except ValueError as exc:
            skin.error(f"Parse error: {exc}")
            continue

        try:
            cli.main(args=args, prog_name="cli-anything-capcut", standalone_mode=False)
        except SystemExit:
            pass
        except Exception as exc:
            skin.error(str(exc))

    skin.print_goodbye()
    _repl_mode = False


def main() -> None:
    """Entry point for console_scripts."""
    cli(prog_name="cli-anything-capcut")


if __name__ == "__main__":
    main()

