def _to_rel_posix(target_path: str, base_dir: str) -> str:
    """Convert `target_path` to a portable POSIX relative path from `base_dir` when on the same drive."""
    try:
        abs_target = os.path.abspath(target_path)
        abs_base = os.path.abspath(base_dir)
        rel = os.path.relpath(abs_target, abs_base)
        return rel.replace("\\", "/")
    except ValueError:
        return target_path.replace("\\", "/")


def _resolve_from_base(stored_path: str, base_dir: str) -> str:
    """Resolve a portable relative path against `base_dir`."""
    if not stored_path:
        return stored_path
    if os.path.isabs(stored_path) and os.path.exists(stored_path):
        return os.path.normpath(stored_path)
    cand = os.path.normpath(os.path.join(base_dir, stored_path))
    if os.path.exists(cand) or not os.path.isabs(stored_path):
        return cand
    return os.path.normpath(stored_path)


def serialize_portable_project(project: Dict[str, Any], target_file_path: str) -> Dict[str, Any]:
    """Return a copy of `project` with all media/SRT paths converted to relative POSIX paths for distribution."""
    base_dir = os.path.dirname(os.path.abspath(target_file_path)) or "."
    portable = deepcopy(project)
    portable.pop("_base_dir", None)
    for seg in portable.get("segments", []):
        if seg.get("path"):
            seg["path"] = _to_rel_posix(seg["path"], base_dir)
    for srt in portable.get("srt_imports", []):
        if srt.get("srt_path"):
            srt["srt_path"] = _to_rel_posix(srt["srt_path"], base_dir)
    if portable.get("native_draft_path"):
        portable["native_draft_path"] = _to_rel_posix(
            portable["native_draft_path"], base_dir
        )
    return portable


def resolve_portable_project(project: Dict[str, Any], source_file_path: str) -> Dict[str, Any]:
    """Resolve portable relative paths in `project` against `source_file_path`'s directory."""
    base_dir = os.path.dirname(os.path.abspath(source_file_path)) or "."
    project["_base_dir"] = base_dir
    for seg in project.get("segments", []):
        if seg.get("path"):
            seg["rel_path"] = _to_rel_posix(
                _resolve_from_base(seg["path"], base_dir), base_dir
            )
            seg["path"] = _resolve_from_base(seg["path"], base_dir)
    for srt in project.get("srt_imports", []):
        if srt.get("srt_path"):
            srt["srt_path"] = _resolve_from_base(srt["srt_path"], base_dir)
    if project.get("native_draft_path"):
        project["native_draft_path"] = _resolve_from_base(
            project["native_draft_path"], base_dir
        )
    return project


def open(path: str) -> Dict[str, Any]:
    """Open a CLI-Anything CapCut project file or native `draft_content.json`, resolving relative paths."""
    abs_path = os.path.abspath(path)
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Project file not found: {abs_path}")

    with builtins_open(abs_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Support opening either our project schema or a raw CapCut draft_content.json
    if data.get("schema") == "cli-anything-capcut/v1":
        resolve_portable_project(data, abs_path)
        invalidate_project_index(data)
        return data

    if "canvas_config" in data and "tracks" in data and "materials" in data:
        cc_canvas = data.get("canvas_config", {})
        proj = {
            "schema": "cli-anything-capcut/v1",
            "name": os.path.basename(os.path.dirname(abs_path)) or "Imported Draft",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "canvas": {
                "width": int(cc_canvas.get("width", 1920)),
                "height": int(cc_canvas.get("height", 1080)),
                "fps": int(data.get("fps", 30)),
                "maintrack_adsorb": bool(
                    data.get("config", {}).get("maintrack_adsorb", True)
                ),
            },
            "tracks": [
                {
                    "name": t.get("name") or t.get("type", "video"),
                    "type": t.get("type", "video"),
                    "mute": bool(t.get("attribute", 0)),
                    "relative_index": 0,
                }
                for t in data.get("tracks", [])
            ],
            "segments": [],
            "srt_imports": [],
            "duration_us": int(data.get("duration", 0)),
            "native_draft_path": abs_path,
            "_dirty_segments": [],
            "_structure_dirty": False,
        }
        resolve_portable_project(proj, abs_path)
        invalidate_project_index(proj)
        return proj

    raise ValueError(f"Unrecognized CapCut project format in {abs_path}")


def builtins_open(*args: Any, **kwargs: Any) -> Any:
    """Wrapper around built-in open since module defines `open`."""
    import builtins

    return builtins.open(*args, **kwargs)


open_project = open


def save(project: Dict[str, Any], path: str) -> str:
    """Save a CapCut project dictionary to `path` with portable relative paths using locked JSON write."""
    abs_path = os.path.abspath(path)
    recompute_duration(project)
    portable = serialize_portable_project(project, abs_path)
    _locked_save_json(abs_path, portable, indent=2, ensure_ascii=False)
    return abs_path
